# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, G, T, M, I = "Lucas", "Amparo", "Alejandra", "Treviño", "Mauricio", "Iván"
D = [
("#", "Escena 1 · 8:30 · Sala de juntas de Garza Acabados, Monterrey", "장면 1 · 오전 8시 30분 · 몬테레이, 가르사 아카바도스 회의실"),
(None, "Lunes 28 de abril. Afuera ya hace treinta grados. Sobre la mesa hay tres copias del contrato de distribución, llenas de banderitas de colores. El licenciado Treviño ha llegado puntual, algo que Lucas ya no da por hecho en Monterrey.", "4월 28일 월요일. 바깥은 벌써 30도다. 테이블 위에는 색색의 작은 견출지가 잔뜩 붙은 유통 계약서 세 부가 놓여 있다. 트레비뇨 변호사는 정시에 왔다. 몬테레이에서 루카스가 더는 당연하게 여기지 않게 된 일이다."),
(T, "Buenos días, licenciados. Si les parece, vamos punto por punto. Quedan tres banderitas: la amarilla, la verde y la roja.", "안녕하세요, 두 분. 괜찮으시면 한 항목씩 보겠습니다. 견출지가 세 개 남았습니다. 노란색, 초록색, 빨간색."),
(L, "Nos parece muy bien. Empecemos por la amarilla. Es la más fácil, ¿no?", "좋습니다. 노란색부터 하죠. 그게 제일 쉽잖아요?"),
(T, "Para un abogado no hay ninguna fácil, licenciado. La amarilla es la sede del arbitraje. Lo demás ya está en el borrador: Cámara de Comercio Internacional, árbitro único y procedimiento en español. Solo la sede sigue entre corchetes.", "변호사에게 쉬운 항목은 없습니다, 선생님. 노란색은 중재지입니다. 나머지는 초안에 이미 들어 있어요. 국제상업회의소, 단독 중재인, 스페인어 절차. 중재지만 아직 괄호 안에 남아 있습니다."),
(G, "Yo sigo pensando que lo natural es Monterrey. El cliente está aquí, la obra está aquí y yo estoy aquí.", "저는 여전히 몬테레이가 자연스럽다고 생각해요. 고객도 여기 있고, 현장도 여기 있고, 저도 여기 있으니까요."),
(A, "Y la fábrica está en Onda, Alejandra. Ramón sigue pidiendo Madrid. Si un día hay un problema de calidad, las pruebas se harán con nuestras piezas y en nuestro laboratorio.", "그리고 공장은 온다에 있어요, 알레한드라. 라몬은 여전히 마드리드를 원해요. 언젠가 품질 문제가 생기면 시험은 우리 제품으로, 우리 실험실에서 하게 될 거예요."),
(G, "Madrid está a doce horas de avión de mi cliente. Mauricio no va a ir a pelearse a Madrid.", "마드리드는 제 고객한테서 비행기로 열두 시간이에요. 마우리시오가 싸우러 마드리드까지 가진 않을 거예요."),
(L, "Por eso propuse un lugar neutral la semana pasada: Miami o la Ciudad de México.", "그래서 지난주에 중립적인 장소를 제안했잖아요. 마이애미나 멕시코시티요."),
(G, "¿Miami? Ni loca. Allí acabaríamos peleándonos en inglés.", "마이애미요? 절대 안 돼요. 거기선 결국 영어로 싸우게 될 거예요."),
(T, "Entonces, la Ciudad de México. Y como ley aplicable les propongo la Convención de Viena sobre compraventa internacional de mercaderías, que España y México han firmado. Terreno neutral: ni ustedes juegan en casa ni nosotros.", "그럼 멕시코시티로 하죠. 그리고 준거법으로는 스페인과 멕시코가 모두 가입한 국제물품매매에 관한 빈 협약을 제안드립니다. 중립 지역이죠. 그쪽도 우리도 홈경기가 아닙니다."),
(A, "Y el procedimiento en español, como ya dice el borrador.", "그리고 절차는 초안에 있는 대로 스페인어로요."),
(G, "Faltaba más. No nos vamos a pelear en inglés siendo todos hispanohablantes.", "당연하죠. 다 스페인어 쓰는 사람들인데 영어로 싸울 순 없잖아요."),
(L, "Le escribí a Ramón anoche. Su respuesta fue: «Si no es Madrid, que sea una capital. Y que no se alargue». Viniendo de Ramón, es casi un abrazo.", "어젯밤에 라몬한테 메일을 보냈어요. 답장이 '마드리드가 아니면 수도로. 그리고 길어지지만 않게'였어요. 라몬한테서 나온 말이면 거의 포옹이에요."),
(G, "(ríe) Ese señor me cae bien sin conocerlo.", "(웃으며) 그분은 만나 보지도 않았는데 마음에 드네요."),
(T, "Amarilla, resuelta. (quita la banderita) Pasamos a la verde: el banco de la carta de crédito.", "노란색, 해결. (견출지를 뗀다) 초록색으로 넘어가죠. 신용장 은행입니다."),
(A, "Nosotros necesitamos que la carta de crédito la confirme un banco español. Es una condición de nuestro director financiero desde el primer día.", "저희는 신용장을 스페인 은행이 확인해 줘야 해요. 첫날부터 저희 재무이사의 조건이었어요."),
(G, "La emite el Banco del Norte, mi banco de toda la vida. ¿No les basta?", "발행은 제가 평생 거래한 방코 델 노르테가 해요. 그걸로는 부족한가요?"),
(L, "Nos basta como banco emisor. Pero la confirmación de un banco en España nos protege si hay un problema con las transferencias o... de cualquier otro tipo.", "발행 은행으로는 충분해요. 하지만 스페인 은행의 확인이 있으면 송금 문제나… 다른 어떤 문제가 생겨도 저희가 보호받을 수 있어요."),
(G, "De que yo no pague, quiere decir. Dígalo, licenciado, no me ofendo.", "제가 돈을 안 낼 경우 말이죠. 그렇게 말씀하세요, 선생님. 기분 나빠하지 않아요."),
(L, "No lo digo por usted, Alejandra. Lo digo por 2009. (pausa) En 2009 perdimos más de trescientos mil euros con un distribuidor de Guadalajara.", "당신 때문에 하는 말이 아니에요, 알레한드라. 2009년 때문이에요. (잠시 멈춤) 2009년에 저희는 과달라하라의 한 유통업자 때문에 30만 유로 넘게 잃었어요."),
(G, "(se queda callada un momento) No lo sabía. Vicente nunca me lo contó.", "(잠시 말이 없다가) 몰랐어요. 비센테가 한 번도 말해 준 적이 없어요."),
(A, "A mi padre no le gusta contarlo. Por eso le importa tanto este contrato.", "아빠는 그 얘기를 하는 걸 싫어해요. 그래서 이 계약이 아빠한테 그렇게 중요한 거고요."),
(L, "La confirmación no es desconfianza hacia usted. Es memoria.", "확인은 당신을 못 믿어서가 아니에요. 기억 때문이에요."),
(G, "Memoria. Me gusta la palabra. Está bien: el Banco del Norte emite y su banco de Castellón confirma. El costo de la confirmación, mitad y mitad.", "기억이라. 그 말 좋네요. 좋아요. 방코 델 노르테가 발행하고 카스테욘에 있는 그쪽 은행이 확인하는 걸로. 확인 수수료는 반반씩."),
(A, "Mitad y mitad. De acuerdo.", "반반. 좋아요."),
(T, "Una pregunta práctica, licenciado: ¿quién firma por Cerámicas Albalat? En el borrador aparece don Vicente Albalat.", "실무적인 질문 하나 드리죠, 선생님. 세라미카스 알발라트를 대표해 누가 서명합니까? 초안에는 비센테 알발라트 대표님으로 돼 있는데요."),
(L, "Vicente me envió la semana pasada un poder notarial. Está apostillado, como usted nos pidió.", "비센테가 지난주에 공증 위임장을 보내 줬어요. 요청하신 대로 아포스티유도 받았고요."),
(T, "Perfecto. Sin la apostilla, aquí ese papel no valdría nada. Me lo quedo un momento para cotejarlo.", "완벽합니다. 아포스티유가 없으면 여기선 그 서류가 아무 효력이 없거든요. 대조해 보게 잠시 갖고 있겠습니다."),
(G, "¿Ve, licenciado? Hasta los papeles tienen que viajar con pasaporte.", "보셨죠, 선생님? 서류도 여권을 들고 다녀야 한다니까요."),
(T, "Verde, resuelta. Queda la roja, la que más me preocupa: el idioma del contrato.", "초록색, 해결. 빨간색이 남았네요. 제가 제일 걱정하는 항목입니다. 계약서의 언어죠."),
(L, "¿El idioma? Pero si aquí todos hablamos español.", "언어요? 여기선 다들 스페인어를 쓰잖아요."),
(T, "Nosotros sí. Pero el banco que confirmará la carta de crédito en Castellón pide una versión en inglés para su departamento internacional.", "우리는 그렇죠. 하지만 카스테욘에서 신용장을 확인할 은행이 국제 업무 부서용으로 영어본을 요구합니다."),
(A, "Entonces que haya dos versiones. Pero solo una puede mandar si dicen cosas distintas.", "그럼 두 가지 버전을 만들죠. 하지만 내용이 서로 다르면 하나만 우선해야 해요."),
(T, "Exacto. Esa es la cláusula que falta: cuál prevalece en caso de discrepancia.", "바로 그겁니다. 그게 빠진 조항이에요. 불일치가 있을 때 어느 쪽이 우선하느냐."),
(G, "La española, obviamente. Es la que hemos negociado palabra por palabra. Con nosotros, en español; con los bancos, en inglés.", "당연히 스페인어본이죠. 한 단어 한 단어 협상한 게 그거잖아요. 우리끼리는 스페인어로, 은행이랑은 영어로."),
(L, "De acuerdo. Propongo esta redacción: «El presente contrato se redacta en español y en inglés. En caso de discrepancia, la versión en español será considerada la única auténtica».", "좋습니다. 이렇게 쓰자고 제안합니다. '본 계약서는 스페인어와 영어로 작성한다. 불일치가 있을 경우 스페인어본만을 정본으로 간주한다.'"),
(T, "(escribe) «...será considerada la única auténtica...». Me gusta. Lo ha redactado como un abogado, licenciado.", "(받아 적으며) '…정본으로 간주한다…' 좋네요. 변호사처럼 작성하셨네요, 선생님."),
(L, "Ocho años de consultoría. Algo se pega.", "컨설팅 8년이에요. 뭔가 묻어나죠."),
(G, "Pues que se le pegue también lo bueno de aquí, licenciado. Por cierto, es usted el único que llegó a las ocho en punto.", "그럼 여기 좋은 것도 좀 묻어나길 바라요, 선생님. 그런데 8시 정각에 온 사람은 선생님뿐이었어요."),
(T, "Roja, resuelta. (quita la última banderita) Señores, el contrato está listo para su firma.", "빨간색, 해결. (마지막 견출지를 뗀다) 여러분, 계약서는 서명할 준비가 됐습니다."),
(G, "¡Ándale! Mauricio nos espera a las doce. ¡Iván! ¿Ya está la camioneta?", "좋아요! 마우리시오가 12시에 기다려요. 이반! 차 준비됐니?"),
(I, "(asoma la cabeza) Ya está, tía. Y ya imprimí las fotos del vestíbulo para la presentación. Quedaron bien chidas.", "(고개를 들이밀며) 준비됐어요, 이모. 그리고 발표용 로비 사진도 벌써 뽑았어요. 끝내주게 나왔어요."),
(A, "¿Qué presentación?", "무슨 발표요?"),
(I, "¿No les dijeron? El ingeniero Elizondo invitó a la prensa local. Va a haber discursos.", "얘기 못 들으셨어요? 엘리손도 사장님이 지역 언론을 불렀어요. 연설도 있을 거예요."),
(L, "¿Discursos? ¿De quién?", "연설이요? 누가요?"),
(G, "De Mauricio, mío... y suyo, licenciado. Cinco minutos. No se ponga pálido.", "마우리시오, 저… 그리고 선생님이요. 5분이에요. 얼굴 하얘지지 마세요."),

("#", "Escena 2 · 12:00 · Piso 18 de la Torre Cumbres, San Pedro Garza García", "장면 2 · 정오 · 산페드로가르사가르시아, 토레 쿰브레스 18층"),
(None, "Por los ventanales se ve la silueta del Cerro de la Silla. Hay un atril, dos fotógrafos, una mesa con mantel blanco y, en el centro, una placa de muestra del «Blanco San Pedro». Mauricio Elizondo reparte apretones de manos y palmadas en la espalda.", "통유리창 너머로 세로 데 라 시야 산의 실루엣이 보인다. 연설대 하나, 사진기자 두 명, 흰 식탁보를 덮은 테이블이 있고, 그 가운데에 '블랑코 산페드로' 샘플 판이 놓여 있다. 마우리시오 엘리손도가 악수를 하고 등을 두드리며 돌아다닌다."),
(M, "¡Bienvenidos, bienvenidos! Licenciado, licenciada, hoy es un gran día para San Pedro.", "어서 오세요, 어서 오세요! 선생님, 선생님, 오늘은 산페드로에 큰 날입니다."),
(L, "Gracias por recibirnos, Mauricio. Y por esta vista.", "맞아 주셔서 감사합니다, 마우리시오. 이 전망도요."),
(M, "La vista es gratis. Los departamentos, no. (risas) ¿Ya revisaron todo con Héctor?", "전망은 공짜예요. 아파트는 아니고요. (웃음) 엑토르랑 다 검토하셨어요?"),
(T, "Todo revisado, ingeniero. Quedaban tres puntos y los tres se resolvieron esta mañana.", "다 검토했습니다, 사장님. 세 가지가 남아 있었는데 오늘 아침에 모두 해결됐습니다."),
(M, "Así me gusta. En Monterrey se trabaja rápido... cuando se quiere. (a Amparo) Licenciada, ¿ya les contó a sus químicos lo de mi alberca?", "그래야죠. 몬테레이에선 일을 빨리 합니다… 마음만 먹으면요. (암파로에게) 선생님, 우리 집 수영장 얘기는 화학자분들한테 전하셨어요?"),
(A, "Se lo conté a Maribel, nuestra responsable de calidad. Dice que su alberca necesita una pieza con más relieve en el borde. Le mandaremos muestras en el segundo envío.", "저희 품질 책임자 마리벨한테 얘기했어요. 사장님 수영장 가장자리에는 요철이 더 있는 제품이 필요하대요. 두 번째 배송 때 샘플을 보내 드릴게요."),
(M, "¿Ve, Ale? Por esto me gustan estos españoles. Se acuerdan de todo.", "봤지, 알레? 이래서 이 스페인 사람들이 마음에 든다니까. 뭐든 다 기억해."),
(G, "Se acuerdan de todo y lo cobran todo, Mauricio. No te emociones. ¿Empezamos?", "다 기억하고 다 돈 받아요, 마우리시오. 너무 들뜨지 마. 시작할까?"),
(M, "Empecemos.", "시작하죠."),
(G, "Antes de firmar, déjenme confirmar los números en voz alta, para que nadie se lleve sorpresas.", "서명하기 전에 숫자를 소리 내서 확인할게요. 아무도 놀라지 않게요."),
(M, "Adelante.", "그래요."),
(G, "Primero: Cerámicas Albalat suministrará cuarenta mil metros cuadrados de porcelánico para las dos torres, a quince euros con noventa y cuatro el metro, puesto en Monterrey.", "첫째, 세라미카스 알발라트는 아파트 두 동에 자기질 타일 4만㎡를 ㎡당 15.94유로, 몬테레이 도착 조건으로 공급한다."),
(A, "Correcto.", "맞아요."),
(G, "Segundo: dos mil metros cuadrados de placa de gran formato «Blanco San Pedro», de ciento veinte por doscientos sesenta, para el vestíbulo del hotel. A treinta y ocho euros con cincuenta el metro, también puesto en Monterrey.", "둘째, 호텔 로비용 120×260 대형 판 '블랑코 산페드로' 2,000㎡. ㎡당 38.50유로, 역시 몬테레이 도착 조건."),
(L, "Correcto. Y con el diseño de Nuria adaptado sin coste.", "맞습니다. 그리고 누리아의 디자인은 무상으로 맞춰 드리고요."),
(G, "Tercero: treinta por ciento de anticipo dentro de las cuarenta y ocho horas siguientes a la firma; el setenta por ciento restante, con carta de crédito confirmada. Y cuarto: el diseño «Blanco San Pedro» será exclusivo de Garza Acabados en México durante tres años.", "셋째, 서명 후 48시간 안에 선수금 30%, 나머지 70%는 확인 신용장으로. 그리고 넷째, '블랑코 산페드로' 디자인은 3년 동안 멕시코에서 가르사 아카바도스만 독점한다."),
(M, "Y si la segunda fase arranca en enero, otros cincuenta mil metros para dos torres más. Pero eso, licenciado, depende de cómo pisen los primeros.", "그리고 2단계가 1월에 시작되면 아파트 두 동에 또 5만㎡예요. 하지만 그건요, 선생님, 첫 번째 바닥들이 어떻게 밟히느냐에 달렸죠."),
(A, "Los primeros van a pisar bien, Mauricio. De eso nos encargamos nosotros.", "첫 번째 바닥들은 잘 밟힐 거예요, 마우리시오. 그건 저희가 책임질게요."),
(M, "¿Y la entrega? Eso es lo que me quita el sueño.", "납품은요? 그게 제 잠을 못 자게 하는 거예요."),
(A, "El primer embarque saldrá de Valencia seis semanas después de recibir el anticipo. Después, entre ocho y diez contenedores por semana.", "첫 선적은 선수금을 받고 6주 뒤에 발렌시아에서 출발해요. 그다음엔 매주 8~10개 컨테이너씩이에요."),
(M, "¿Y el vestíbulo, cuándo llega? El hotel abre el primero de diciembre y la decoradora ya me llama cada semana.", "로비 건은 언제 와요? 호텔이 12월 1일에 문을 여는데 인테리어 디자이너가 벌써 매주 전화해요."),
(A, "Las placas grandes se fabricarán en el horno tres en junio. Saldrán en el tercer embarque, a principios de julio.", "대형 판은 6월에 3호기에서 생산할 거예요. 세 번째 선적으로 7월 초에 출발해요."),
(M, "¿Y si se rompen en el camino? Son placas de dos metros sesenta.", "가는 길에 깨지면요? 2미터 60짜리 판인데."),
(L, "Viajan de canto, en caballetes de madera, como los cristales. Y el seguro cubre la rotura hasta Monterrey.", "유리처럼 나무 받침대에 세워서 운반해요. 그리고 몬테레이까지는 보험이 파손을 보장하고요."),
(G, "Y el seguro lo paga Albalat, Mauricio. Ya está incluido en el precio.", "보험료는 알발라트가 내, 마우리시오. 가격에 이미 들어가 있어."),
(M, "¿Y cuántos contenedores en total?", "총 몇 개예요?"),
(L, "Unos treinta y dos. Treinta para las torres y dos para el vestíbulo.", "32개 정도요. 아파트용 30개, 로비용 2개."),
(M, "Treinta y dos... (silba) Y los italianos me pedían diez semanas solo para el primero.", "32개라… (휘파람을 분다) 이탈리아 쪽은 첫 번째 것만 10주가 걸린다고 했는데."),
(G, "Mauricio, por favor. El hotel ya es de ellos. Hoy no venimos a hablar de italianos.", "마우리시오, 제발. 호텔은 이미 그쪽 거야. 오늘은 이탈리아 얘기하러 온 거 아니잖아."),
(M, "Tienes razón, Ale. Hoy se habla de españoles. ¡Héctor, los papeles!", "네 말이 맞아, 알레. 오늘은 스페인 사람들 얘기만 하자. 엑토르, 서류!"),
(None, "Treviño reparte las tres copias. Firman Alejandra y Lucas, este en nombre de Cerámicas Albalat con el poder notarial que Vicente le envió la semana pasada. Mauricio y Amparo firman como testigos. Los fotógrafos disparan. Iván lo graba todo con el celular.", "트레비뇨가 계약서 세 부를 나눠 준다. 알레한드라와 루카스가 서명한다. 루카스는 지난주 비센테가 보내 준 공증 위임장으로 세라미카스 알발라트를 대표해 서명한다. 마우리시오와 암파로는 증인으로 서명한다. 사진기자들이 셔터를 누르고, 이반은 휴대폰으로 전부 찍는다."),
(T, "Firmado en Monterrey, Nuevo León, a veintiocho de abril, por triplicado y a un solo efecto.", "누에보레온주 몬테레이에서 4월 28일, 동일한 효력을 갖는 세 부로 서명함."),
(M, "¡Aplausos! Y ahora, los discursos. Cortitos, que ya tengo hambre. Ale, tú primero.", "박수! 이제 연설이요. 짧게 합시다, 벌써 배고파요. 알레, 너부터."),
(G, "(en el atril) Gracias. Hace tres meses entré en un hotel de Valencia y me enamoré de un piso. Llamé a la fábrica y me contestó un señor que llevaba un día en la empresa. (risas)", "(연설대에서) 감사합니다. 석 달 전 저는 발렌시아의 한 호텔에 들어갔다가 바닥에 반했습니다. 공장에 전화했더니 입사한 지 하루 된 분이 받더군요. (웃음)"),
(M, "(desde el fondo) ¡Y todavía no se ha ido!", "(뒤쪽에서) 그리고 아직 안 떠났죠!"),
(G, "No me prometió nada que no pudiera cumplir. Bueno, casi nada. Le agradezco su paciencia. Y a la licenciada Albalat le agradezco que me haya dicho que no tantas veces. Que esta relación sea larga y que nos traiga muchos pisos. ¡Salud!", "그분은 지킬 수 없는 약속은 하나도 하지 않았습니다. 음, 거의 하나도요. 그분의 인내에 감사드립니다. 그리고 저에게 그렇게 여러 번 '안 된다'고 말해 준 알발라트 선생님께도 감사드립니다. 이 관계가 오래가고, 우리에게 많은 바닥을 가져다주기를 바랍니다. 건배!"),
(M, "¡Muy bien! Licenciado Ferrer, su turno.", "아주 좋아요! 페레르 선생님, 차례입니다."),
(L, "(respira hondo) Buenas tardes. Yo no soy de Monterrey y, como algunos de ustedes saben, tampoco soy de Onda. Soy de Madrid. (risas) En estos tres meses he aprendido que ahorita no es ahora, que el piso es el suelo y que hay palabras que no se dicen. (más risas)", "(깊게 숨을 쉬고) 안녕하세요. 저는 몬테레이 사람이 아닙니다. 몇몇 분은 아시겠지만 온다 사람도 아니에요. 마드리드 사람입니다. (웃음) 이 석 달 동안 저는 아오리타가 지금이 아니라는 것, 피소가 바닥이라는 것, 그리고 해서는 안 되는 말이 있다는 걸 배웠습니다. (더 큰 웃음)"),
(I, "¡Eso es cierto, licenciado! ¡Yo soy testigo!", "그건 사실이에요, 선생님! 제가 증인이에요!"),
(L, "Pero también he aprendido que una fábrica de Onda y una familia de Monterrey se parecen mucho: las dos creen que las cosas se hacen bien o no se hacen. Dentro de seis semanas, el primer contenedor saldrá de Valencia. En diciembre, cientos de personas caminarán sobre este suelo.", "하지만 온다의 공장과 몬테레이의 가족이 아주 닮았다는 것도 배웠습니다. 둘 다 일은 제대로 하든지 아예 안 하든지 둘 중 하나라고 믿습니다. 6주 뒤 첫 컨테이너가 발렌시아를 떠날 겁니다. 12월이면 수백 명이 이 바닥 위를 걸을 겁니다."),
(G, "(en voz baja, a Amparo) Este hombre ya habla como regio.", "(암파로에게 작은 목소리로) 이 사람, 벌써 레히오처럼 말하네."),
(A, "(en voz baja) No se lo digas, que se lo cree.", "(작은 목소리로) 그 말 하지 마요, 진짜로 믿어요."),
(L, "(toca la placa de muestra) Les prometo una cosa: cuando lo hagan, nadie pensará en nosotros. Y eso significará que habremos hecho bien nuestro trabajo. Muchas gracias.", "(샘플 판을 만지며) 한 가지 약속드립니다. 그분들이 이 위를 걸을 때 아무도 우리를 떠올리지 않을 겁니다. 그렇다면 우리가 일을 제대로 해냈다는 뜻일 겁니다. 감사합니다."),
(M, "¡Bravo! Eso sí es un discurso. Licenciada, ¿usted no va a decir nada?", "브라보! 이게 바로 연설이죠. 선생님, 선생님은 아무 말씀 안 하세요?"),
(A, "Solo dos cosas, Mauricio. Que sea para bien. Y que la próxima carne asada la paguemos nosotros.", "두 가지만요, 마우리시오. 좋은 일이 되기를. 그리고 다음 카르네 아사다는 저희가 내기를."),
(M, "¡Ni lo sueñe! En mi casa no paga nadie. (risas) ¡A comer!", "꿈도 꾸지 마세요! 우리 집에선 아무도 돈 안 냅니다. (웃음) 식사하러 갑시다!"),
(I, "Licenciado, una foto para el Instagram de Garza Acabados. Con la placa, por favor. Sonríale al Cerro.", "선생님, 가르사 아카바도스 인스타그램용 사진 한 장이요. 판이랑 같이요. 산을 보고 웃어 주세요."),
(L, "¿Al Cerro?", "산을 보고요?"),
(I, "Es que aquí todo el mundo le sonríe al Cerro de la Silla. Es tradición. Bueno, me la acabo de inventar. ¡Ya, quedó!", "여기선 다들 세로 데 라 시야한테 웃어 줘요. 전통이에요. 음, 방금 지어낸 거지만요. 됐다, 잘 나왔어요!"),

("#", "Escena 3 · 5:45 (día siguiente) · Camino al aeropuerto de Monterrey", "장면 3 · 다음 날 오전 5시 45분 · 몬테레이 공항 가는 길"),
(None, "Martes 29 de abril. Todavía es de noche. La misma camioneta que los recogió hace veinte días los lleva al aeropuerto. Iván conduce con la radio baja. Amparo revisa el móvil: la transferencia del anticipo aparece como «en proceso».", "4월 29일 화요일. 아직 캄캄하다. 20일 전 두 사람을 태웠던 그 차가 이번에는 공항으로 데려간다. 이반이 라디오를 작게 틀고 운전한다. 암파로가 휴대폰을 확인한다. 선수금 송금이 '처리 중'으로 떠 있다."),
(I, "¿Neta ya se van? Se me hizo rapidísimo.", "진짜 벌써 가요? 엄청 빨리 지나간 것 같아요."),
(A, "Veinte días, Iván. A nosotros nos han parecido tres meses.", "20일이야, 이반. 우리한텐 석 달 같았어."),
(I, "Pues regresen pronto, güey. Uy, perdón, licenciada. Regrese pronto.", "그럼 빨리 돌아와, 친구. 아, 죄송해요, 선생님. 빨리 돌아오세요."),
(A, "(ríe) «Güey» está bien, Iván. Ya me lo has explicado tres veces.", "(웃으며) '구에이' 괜찮아, 이반. 벌써 세 번이나 설명해 줬잖아."),
(L, "¿Y el anticipo? ¿Ya se ve?", "선수금은요? 벌써 보여요?"),
(A, "«Transferencia en proceso». Ramón dice que mañana estará en la cuenta.", "'송금 처리 중'. 라몬 말로는 내일 계좌에 들어올 거래요."),
(L, "Entonces mañana empieza a correr el reloj. Seis semanas.", "그럼 내일부터 시계가 돌기 시작하네요. 6주."),
(A, "El horno tres ya lleva un mes encendido. Paco me ha mandado una foto: está con el chaleco puesto, esperando la primera orden de fabricación.", "3호기는 벌써 한 달째 켜져 있어요. 파코가 사진을 보냈는데, 조끼를 입고 첫 생산 지시를 기다리고 있대요."),
(I, "Oigan, ¿y qué le van a decir a su papá, licenciada? ¿Que perdieron el hotel?", "근데요, 아버님한테는 뭐라고 하실 거예요, 선생님? 호텔을 놓쳤다고요?"),
(A, "Le voy a decir que perdimos las habitaciones y ganamos el vestíbulo. Y que en un hotel el vestíbulo es lo primero que se ve.", "객실은 놓치고 로비를 얻었다고 할 거야. 그리고 호텔에서 제일 먼저 보이는 게 로비라고."),
(I, "¡Qué chingón! Uy, perdón. Esa no se dice.", "완전 끝내주네요! 아, 죄송해요. 그건 하면 안 되는 말이죠."),
(L, "Esa no se dice en un bautizo, Iván. En la camioneta, a las seis de la mañana, creo que está permitida.", "그건 세례식에서 하면 안 되는 말이지, 이반. 새벽 6시에 차 안에서는 허락되는 것 같아."),
(I, "(ríe) Ya aprendió, licenciado. Ya es medio regio.", "(웃으며) 다 배우셨네요, 선생님. 이제 반쯤은 레히오예요."),
(L, "¿Regio?", "레히오?"),
(I, "Regiomontano. De Monterrey. Y medio, porque todavía pide el café sin azúcar.", "레히오몬타노. 몬테레이 사람이요. 반쯤인 건 아직도 커피를 설탕 없이 시키시니까요."),
(A, "¿Y tú, Iván? ¿Vendrás algún día a Onda?", "너는, 이반? 언젠가 온다에 올 거야?"),
(I, "Si mi tía me deja, a la próxima feria de Valencia. Dice que primero tengo que aprender a vender, no solo a sacar fotos.", "이모가 허락하면 다음 발렌시아 박람회 때요. 사진만 찍지 말고 파는 법부터 배우래요."),
(L, "Pues tus fotos de ayer ya han vendido algo: Ramón las ha visto y ha contestado con un pulgar hacia arriba. Viniendo de Ramón, es una fiesta.", "어제 네 사진은 벌써 뭔가 팔았어. 라몬이 보고 엄지척으로 답장했거든. 라몬한테서 나온 거면 잔치야."),
(None, "Llegan a la terminal. Iván baja las maletas. Esta vez no hay caja de madera: las muestras se quedan en el showroom de Garza Acabados.", "터미널에 도착한다. 이반이 가방을 내린다. 이번엔 나무 상자가 없다. 샘플은 가르사 아카바도스 쇼룸에 남는다."),
(I, "Me dijo mi tía que les diera esto. (les da una bolsa) Glorias de Linares. Dulces de leche de cabra. Para el avión.", "이모가 이거 드리래요. (봉투를 건넨다) 리나레스의 글로리아스예요. 염소젖 캐러멜 과자. 비행기에서 드세요."),
(A, "Gracias, Iván. Dale las gracias a tu tía de nuestra parte.", "고마워, 이반. 이모님께 우리 대신 감사하다고 전해 줘."),
(I, "Se las doy. Y dice que la llamen cuando lleguen. No ahorita: cuando lleguen.", "전할게요. 그리고 도착하면 전화 달래요. 아오리타 말고요. 도착하면요."),
(L, "(sonríe) Entendido. Cuando lleguemos.", "(미소 지으며) 알겠어. 도착하면."),
(None, "Iván se despide con un abrazo largo, a la mexicana. Ya en la puerta de embarque, Lucas saca de la cartera el trozo de baldosa de 1958 y lo mira un momento.", "이반이 멕시코식으로 길게 끌어안으며 작별 인사를 한다. 탑승구 앞에서 루카스가 서류 가방에서 1958년 타일 조각을 꺼내 잠시 바라본다."),
(A, "¿Se lo vas a devolver a Pepe?", "그거 페페한테 돌려줄 거예요?"),
(L, "Todavía no. Lo voy a guardar hasta que salga el primer contenedor. Luego ya veremos.", "아직은요. 첫 컨테이너가 나갈 때까지 갖고 있을 거예요. 그다음에 생각해 보죠."),
(A, "Seis semanas. Y en el avión le escribimos juntos a Camilo, como quedamos.", "6주. 그리고 비행기에서 카밀로한테 같이 메일 써요, 약속한 대로."),
(L, "Seis semanas. Y a Camilo, juntos. (guarda la baldosa) Vámonos a casa, socia.", "6주. 그리고 카밀로한테는 같이. (타일 조각을 집어넣으며) 집에 갑시다, 파트너."),
(A, "Vámonos a casa, socio.", "집에 가요, 파트너."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "서명 당일 아침, 트레비뇨 변호사가 계약서에 남은 견출지 세 개를 하나씩 떼어 낸다. 준거법과 중재, 신용장 은행, 계약서의 언어다. 루카스는 처음으로 알레한드라에게 2009년의 손실을 털어놓는다. 정오에는 산페드로의 고층 빌딩에서 서명식이 열리고, 루카스는 예고 없이 연설대에 선다. 다음 날 새벽, 20일 전 두 사람을 태웠던 그 차가 다시 공항으로 향한다.",
 "듣기 질문 ① 준거법과 중재지는 각각 어떻게 정해졌는가? 왜 그 장소인가?",
 "듣기 질문 ② 알발라트가 공급하는 물량과 가격은? 컨테이너는 모두 몇 개이고, 블랑코 산페드로 디자인에는 어떤 조건이 붙는가?",
 "듣기 질문 ③ 암파로는 아버지에게 결과를 어떻게 전하겠다고 하는가?",
]),
]

